#include <iostream>
#include <vector>
#include <queue>
#include <deque>
using namespace std;

struct Child {
    int v, d, p;
    int idx;
};

int main() {
    int n;
    cin >> n;
    vector<Child> children(n);
    for (int i = 0; i < n; ++i) {
        cin >> children[i].v >> children[i].d >> children[i].p;
        children[i].idx = i + 1;
    }

    deque<Child> queue;
    for (int i = 0; i < n; ++i) {
        queue.push_back(children[i]);
    }

    vector<int> result;
    while (!queue.empty()) {
        // Treat the first child
        Child current = queue.front();
        queue.pop_front();
        result.push_back(current.idx);

        int v = current.v;
        int idx = 0;
        for (int i = 0; i < v && !queue.empty(); ++i) {
            idx = i;
            queue[idx].p -= v - i;
        }

        // Check for any child with p < 0
        bool processed = false;
        while (true) {
            bool found = false;
            for (int i = 0; i < queue.size(); ++i) {
                if (queue[i].p < 0) {
                    found = true;
                    break;
                }
            }
            if (!found) break;

            // Find the first child with p < 0
            for (int i = 0; i < queue.size(); ++i) {
                if (queue[i].p < 0) {
                    // Remove this child
                    queue.erase(queue.begin() + i);
                    // Decrease p of all children after this one
                    for (int j = i; j < queue.size(); ++j) {
                        queue[j].p -= queue[i].d;
                    }
                    // Process again
                    processed = true;
                    break;
                }
            }
        }
    }

    cout << result.size() << endl;
    for (int i : result) {
        cout << i << " ";
    }
    cout << endl;
    return 0;
}

