        // Treat the first child
        Child curr = q.front();
        q.pop_front();
        result.push_back(curr.idx);

        int v = curr.v;
        int pos = 0;
        while (pos < q.size() && pos < v) {
            Child& c = q[pos];
            c.p -= v - pos;
            if (c.p < 0) {
                // This child cries and leaves
                q.erase(q.begin() + pos);
                int d = c.d;
                for (int i = pos; i < q.size(); ++i) {
                    q[i].p -= d;
                }
                // Check if any other child is now negative
