            verticals.push_back({y_min, y_max});
        } else { // horizontal segment
            int x_min = min(x1, x2);
            int x_max = max(x1, x2);
            horizontals.push_back({x_min, x_max});
        }
    }

    sort(verticals.begin(), verticals.end());
    sort(horizontals.begin(), horizontals.end());

    int res = 0;
    int prev_v = -1;

    for (auto& v : verticals) {
        if (v.first > prev_v) {
            res += v.second - v.first + 1;
            prev_v = v.second;
        }
    }

    prev_v = -1;
    for (auto& h : horizontals) {
        if (h.first > prev_v) {
            res += h.second - h.first + 1;
            prev_v = h.second;
        }
    }

    cout << res << endl;
}

