    while (power <= r) {
        if (power >= l) {
            result.push_back(power);
        }
        if (power > r / k) break;
        power *= k;
    }

    if (result.empty()) {
        cout << "-1" << endl;
    } else {
        for (size_t i = 0; i < result.size(); ++i) {
            if (i > 0) cout << " ";
            cout << result[i];
        }
        cout << endl;
    }

    return 0;
}

