#include <bits/stdc++.h>
using namespace std;

bool is_beautiful(string s) {
    int ones = 0;
    for (char c : s) {
        if (c == '1') ones++;
        else if (c != '0') return false;
    }
    return ones <= 1;
}

string multiply(string a, string b) {
    int len_a = a.length(), len_b = b.length();
    vector<int> result(len_a + len_b, 0);
    for (int i = len_a - 1; i >= 0; i--) {
        for (int j = len_b - 1; j >= 0; j--) {
            result[i + j + 1] += (a[i] - '0') * (b[j] - '0');
            result[i + j + 1] %= 10;
        }
    }
    // Remove leading zeros
    int idx = 0;
    while (idx < result.size() && result[idx] == 0) idx++;
    if (idx == result.size()) return "0";
    string res;
    for (int i = idx; i < result.size(); i++) {
        res += to_string(result[i]);
    }
    return res;
}

int main() {
    int n;
    cin >> n;
    vector<string> a;
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        a.push_back(s);
    }

    string product = "1";
    for (string s : a) {
        if (s == "0") {
            cout << "0\n";
            return 0;
        }
        product = multiply(product, s);
    }
    cout << product << "\n";
    return 0;
}

