#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

string flip(string s) {
    reverse(s.begin(), s.end());
    while (s.size() > 1 && s.back() == '0') {
        s.pop_back();
    }
    return s;
}

bool check(string a, string n) {
    string ar = flip(a);
    string sum = to_string(stoll(a) + stoll(ar));
    return sum == n;
}

string solve(string n) {
    for (int len = 1; len <= n.size(); ++len) {
        vector<string> digits;
        for (int i = 0; i < len; ++i) {
            digits.push_back(string(1, n[i]));
        }
        do {
            string a = "";
            for (auto d : digits) a += d;
            if (a[0] == '0') continue;
            if (check(a, n)) return a;
        } while (next_permutation(digits.begin(), digits.end()));
    }
    return "0";
}

int main() {
    string n;
    cin >> n;
    cout << solve(n) << endl;
    return 0;
}

