int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> males, females;
    for (int i = 0; i < n; ++i) {
        string gender;
        int a, b;
        cin >> gender >> a >> b;
        if (gender == "M") males.push_back({a, b});
        else females.push_back({a, b});
    }

    int max_people = 0;

    for (int day = 1; day <= 366; ++day) {
        int m = 0, f = 0;
        for (auto& [a, b] : males) {
            if (a <= day && day <= b) ++m;
        }
        for (auto& [a, b] : females) {
            if (a <= day && day <= b) ++f;
        }
        int total = min(m, f) * 2;
        max_people = max(max_people, total);
    }

    cout << max_people << endl;
    return 0;
}

