#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i)
        cin >> a[i];

    int min_pos = -1, max_pos = -1;
    for (int i = 0; i < n; ++i) {
        if (a[i] == 1) min_pos = i;
        if (a[i] == n) max_pos = i;
    }

    int max_dist = abs(min_pos - max_pos);

    for (int i = 0; i < n; ++i) {
        if (a[i] == 1 || a[i] == n) continue;
        // Try swapping current element with min
        if (a[i] == 1) {
            swap(a[i], a[min_pos]);
            int new_dist = abs(min_pos - max_pos);
            max_dist = max(max_dist, new_dist);
            swap(a[i], a[min_pos]);
        }
        // Try swapping current element with max
        if (a[i] == n) {
            swap(a[i], a[max_pos]);
            int new_dist = abs(min_pos - max_pos);
            max_dist = max(max_dist, new_dist);
            swap(a[i], a[max_pos]);
        }
    }

    cout << max_dist << endl;
    return 0;
}

