#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1e5 + 5;

vector<int> adj[MAXN];
bool visited[MAXN];
int color[MAXN];

void dfs(int u, int c) {
    color[u] = c;
    for (int v : adj[u]) {
        if (!visited[v]) {
            visited[v] = true;
            dfs(v, 1 - c);
        }
    }
}

int main() {
    int n, m;
    cin >> n >> m;
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    bool ok = true;
    for (int i = 1; i <= n; ++i) {
        if (!visited[i]) {
            visited[i] = true;
            dfs(i, 0);
        }
    }

    vector<int> A, B;
    for (int i = 1; i <= n; ++i) {
        if (color[i] == 0) {
            A.push_back(i);
        } else {
            B.push_back(i);
        }
    }

    // Check if both A and B are vertex covers
    bool isAvc = true;
    for (int i = 0; i < m; ++i) {
        int u = adj[i][0], v = adj[i][1];
        if (color[u] == 0 && color[v] == 0) {
            isAvc = false;
            break;
        }
    }

    bool isBvc = true;
    for (int i = 0; i < m; ++i) {
        int u = adj[i][0], v = adj[i][1];
        if (color[u] == 1 && color[v] == 1) {
            isBvc = false;
            break;
        }
    }

    if (isAvc && isBvc) {
        cout << A.size() << endl;
        for (int x : A) cout << x << " ";
        cout << endl;
        cout << B.size() << endl;
        for (int x : B) cout << x << " ";
        cout << endl;
    } else {
        cout << "-1" << endl;
    }

    return 0;
}

