                parent[curr] = root;
            }
        }
    }

    // Now, construct the valid sequence
    vector<int> res(n);
    for (int i = 0; i < n; ++i) {
        if (a[i] == i + 1) {
            res[i] = i + 1;
        } else {
            res[i] = parent[i + 1];
        }
    }

    cout << changes << endl;
    for (int i = 0; i < n; ++i) {
        cout << res[i] << " ";
    }
    cout << endl;
}

int main() {
    solve();
    return 0;
}

