    // Each vowel contributes at least one syllable, but can be grouped
    // So the minimum number of syllables is the number of vowels
    return vowel_count;
}

bool check_pattern(int n, vector<int> pattern, vector<string> text) {
    for (int i = 0; i < n; ++i) {
        int total_syllables = 0;
        for (string word : text[i]) {
            if (has_vowel(word)) {
                total_syllables += count_syllables(word);
            }
        }
        if (total_syllables != pattern[i]) {
            return false;
        }
    }
    return true;
}

int main() {
    int n;
    cin >> n;
    vector<int> pattern(n);
    for (int i = 0; i < n; ++i) {
        cin >> pattern[i];
    }
    vector<string> text(n);
    for (int i = 0; i < n; ++i) {
        cin >> text[i];
    }
    if (check_pattern(n, pattern, text)) {
        cout << "YES" << endl;
    } else {
        cout << "NO" << endl;
    }
    return 0;
}

