    int count = 0;

    for (int i = 1; i <= n; ++i) {
        if (visited[i] == 0) {
            int pos = i;
            vector<int> path;
            while (pos >= 1 && pos <= n && visited[pos] == 0) {
                path.push_back(pos);
                visited[pos] = 1;
                if (s[pos - 1] == '<') pos--;
                else pos++;
            }
            if (pos < 1 || pos > n) {
                for (int p : path) visited[p] = 2;
                count += path.size();
            } else {
                for (int p : path) visited[p] = 3;
            }
        }
    }

    cout << count << endl;
    return 0;
}

