int main() {
    int n, s;
    cin >> n >> s;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    map<int, int> cnt;
    for (int i = 0; i < n; ++i) {
        if (a[i] == 0) cnt[s]++;
        else if (a[i] >= 1) cnt[a[i]]++;
    }

    int res = 0;
    for (auto& [k, v] : cnt) {
        if (k == 0) continue;
        int level = k;
        int curr = s;
        bool ok = true;
        while (level > 0) {
            if (cnt.find(curr) == cnt.end()) {
                ok = false;
                break;
            }
            curr = cnt[curr];
            level--;
        }
        if (ok) res += v;
    }

    cout << n - res << endl;
    return 0;
}

