using namespace std;

const int MAX_K = 100;
int K;
int center_row = (K + 1) / 2;
int center_col = (K + 1) / 2;

struct Seat {
    int row;
    int yl;
    int yr;
};

vector<Seat> seats[MAX_K];

bool isAvailable(int row, int yl, int yr) {
    for (int i = yl; i <= yr; ++i) {
        if (seats[row][i] != -1) return false;
    }
    return true;
}

void allocateSeats(int row, int yl, int yr) {
    for (int i = yl; i <= yr; ++i) {
        seats[row][i] = 1;
    }
}

int calculateRemoteness(int row, int yl, int yr) {
    int total = 0;
    for (int i = yl; i <= yr; ++i) {
        total += abs(row - center_row) + abs(i - center_col);
    }
    return total;
}

int main() {
    int N, K;
    cin >> N >> K;
    for (int i = 0; i < K; ++i) {
        vector<int> row_seats(K, -1);
        seats[i] = row_seats;
    }

    for (int i = 0; i < N; ++i) {
        int M;
        cin >> M;
        bool found = false;
        int best_row = -1, best_yl = -1, best_yr = -1;
        int min_remoteness = INT_MAX;

        for (int row = 0; row < K; ++row) {
            for (int yl = 0; yl <= K - M; ++yl) {
                int yr = yl + M - 1;
                if (isAvailable(row, yl, yr)) {
                    int remoteness = calculateRemoteness(row, yl, yr);
                    if (remoteness < min_remoteness || (remoteness == min_remoteness && row < best_row) || (remoteness == min_remoteness && row == best_row && yl < best_yl)) {
                        min_remoteness = remoteness;
                        best_row = row;
                        best_yl = yl;
                        best_yr = yr;
                        found = true;
                    }
                }
            }
        }

        if (!found) {
            cout << "-1\n";
        } else {
            cout << best_row + 1 << " " << best_yl + 1 << " " << best_yr + 1 << "\n";
            allocateSeats(best_row, best_yl, best_yr);
        }
    }

    return 0;
}

