    string class_;
    int atk;
    int def;
    int res;
    int size;
    map<string, int> residents; // resident name -> bonus
};

struct Resident {
    string name;
    string type;
    int bonus;
    string home;
};

vector<Item> items;
vector<Resident> residents;

void parse_items(int n) {
    for (int i = 0; i < n; ++i) {
        string name, class_;
        int atk, def, res, size;
        cin >> name >> class_ >> atk >> def >> res >> size;
        items.push_back({name, class_, atk, def, res, size, {}});
    }
}

void parse_residents(int k) {
    for (int i = 0; i < k; ++i) {
        string name, type;
        int bonus;
        string home;
        cin >> name >> type >> bonus >> home;
        residents.push_back({name, type, bonus, home});
    }
}

void move_residents() {
    for (auto& r : residents) {
        items[find_if(items.begin(), items.end(), [&](Item& i) { return i.name == r.home; }) - items.begin()].residents[r.name] = r.bonus;
    }
}

void find_optimal_equipment() {
