    vector<Item*> weapons;
    for (auto& i : items) {
        if (i.class_ == "weapon") weapons.push_back(&i);
    }

    // Sort weapons by atk + resident bonuses
    sort(weapons.begin(), weapons.end(), [](Item* a, Item* b) {
        int a_total = a->atk;
        for (auto& r : a->residents) a_total += r.second;
        int b_total = b->atk;
        for (auto& r : b->residents) b_total += r.second;
        return a_total > b_total;
    });

