        for (auto& r : a->residents) a_total += r.second;
        int b_total = b->def;
        for (auto& r : b->residents) b_total += r.second;
        return a_total > b_total;
    });

    Item* best_armor = armors[0];

    // Now find orb with max res
    vector<Item*> orbs;
