using namespace std;

double comb(int n, int k) {
    if (k < 0 || k > n) return 0;
    double res = 1.0;
    for (int i = 0; i < k; ++i) {
        res *= (n - i);
        res /= (i + 1);
    }
    return res;
}

int main() {
    int n, m, h;
    cin >> n >> m >> h;
    vector<int> s(m);
    for (int i = 0; i < m; ++i) {
