        cout << "-1" << endl;
        return 0;
    }

    int sh = s[h - 1];
    if (sh == 0) {
        cout << "0" << endl;
        return 0;
    }

    double total_ways = comb(total - 1, n - 1);
    double favorable_ways = 0;

    for (int i = 1; i <= min(sh - 1, n - 1); ++i) {
        int remaining = n - i;
        int other = total - sh;
        if (remaining > other) continue;
        favorable_ways += comb(sh - 1, i) * comb(other, remaining);
    }

    double prob = favorable_ways / total_ways;
    cout << fixed << setprecision(6) << prob << endl;
    return 0;
}

