using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> grid(n);
    for (int i = 0; i < n; ++i)
        cin >> grid[i];

    vector<vector<int>> dirs = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    vector<vector<bool>> visited(n, vector<bool>(m, false));
    int res = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'W') {
                queue<pair<int, int>> q;
                q.push({i, j});
                visited[i][j] = true;
                vector<pair<int, int>> neighbors;

                while (!q.empty()) {
                    int x = q.front().first;
                    int y = q.front().second;
                    q.pop();

                    for (auto &d : dirs) {
                        int nx = x + d[0];
                        int ny = y + d[1];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny]) {
                            visited[nx][ny] = true;
                            if (grid[nx][ny] == 'P') {
                                neighbors.push_back({nx, ny});
                            }
                            q.push({nx, ny});
                        }
                    }
                }

                if (!neighbors.empty()) {
                    sort(neighbors.begin(), neighbors.end());
                    res++;
                }
            }
        }
    }

    cout << res << endl;
    return 0;
}

