    for (int i = 0; i <= k; ++i) {
        int a = n - 2 * i;
        int b = m - 2 * i;
        if (a < 0 || b < 0) continue;
        long long ways = comb[a + b - 1][a - 1];
        ans = (ans + ways) % MOD;
    }
    return ans;
}

