using namespace std;

const int MOD = 1000000007;
const int MAX = 1000;

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    // Precompute factorial and inverse factorial modulo MOD
    long long fact[MAX + 1], inv_fact[MAX + 1];
    fact[0] = 1;
    for (int i = 1; i <= MAX; ++i) {
        fact[i] = fact[i - 1] * i % MOD;
    }
    inv_fact[MAX] = pow(fact[MAX], MOD - 2, MOD);
    for (int i = MAX - 1; i >= 0; --i) {
        inv_fact[i] = inv_fact[i + 1] * (i + 1) % MOD;
    }

    // Function to compute combination C(n, k)
    long long comb(int n, int k) {
        if (k < 0 || k > n) return 0;
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;
    }

    long long ans = 0;

    for (int i = 0; i <= k; ++i) {
        int a = i;
        int b = k - i;

        // Number of ways to choose a rectangles in x direction
        long long x_ways = comb(n - 2, a) * comb(m - 2, a) % MOD;

        // Number of ways to choose b rectangles in y direction
        long long y_ways = comb(n - 2, b) * comb(m - 2, b) % MOD;

        ans = (ans + x_ways * y_ways) % MOD;
    }

    cout << ans << endl;
}

