void dfs(string s, int pos, char turn, vector<char>& cards) {
    if (cards.size() == 2) {
        results[make_pair(cards[0], cards[1])]++;
        return;
    }

    if (pos >= s.size()) return;

    if (s[pos] != '?') {
        cards.push_back(s[pos]);
        dfs(s, pos + 1, turn == 'M' ? 'P' : 'M', cards);
        cards.pop_back();
    } else {
        // Try 0
        cards.push_back('0');
        dfs(s, pos + 1, turn == 'M' ? 'P' : 'M', cards);
        cards.pop_back();

        // Try 1
        cards.push_back('1');
        dfs(s, pos + 1, turn == 'M' ? 'P' : 'M', cards);
        cards.pop_back();
    }
}

