string solve(string s) {
    set<string> res;
    int n = s.size();
    for (int i = 0; i < (1 << n); ++i) {
        string temp = s;
        for (int j = 0; j < n; ++j) {
            if (temp[j] == '?') {
                temp[j] = (i >> j) & 1 ? '1' : '0';
            }
        }
        set<string> outcomes;
        vector<int> positions(n);
        for (int k = 0; k < n; ++k) {
            positions[k] = k;
        }
        function<void(int, int)> dfs = [&](int turn, int pos) {
            if (pos == n - 2) {
                string outcome = temp[positions[pos]] + temp[positions[pos + 1]];
                outcomes.insert(outcome);
                return;
            }
