                if (i & (1 << j)) temp[j] = '1';
                else temp[j] = '0';
            }
        }
        set<pair<char, char>> outcomes;
        vector<char> arr(n);
        for (int j = 0; j < n; ++j) arr[j] = temp[j];
        function<pair<char, char>(int, int)> dfs;
        dfs = [&](int turn, int idx) -> pair<char, char> {
            if (idx == n - 2) return {arr[idx], arr[idx + 1]};
            int next = -1;
            for (int j = 0; j < n; ++j) {
                if (arr[j] != '?') {
                    next = j;
                    break;
                }
            }
            if (next == -1) return {arr[0], arr[1]};
            vector<char> new_arr(arr.begin(), arr.end());
            new_arr.erase(new_arr.begin() + next);
            int new_n = new_arr.size();
            if (new_n == 2) return {new_arr[0], new_arr[1]};
            if (turn % 2 == 0) {
                // Masha's turn: minimize the result
                pair<char, char> best = { '1', '1' };
                for (int j = 0; j < new_n; ++j) {
                    if (new_arr[j] != '?') {
                        vector<char> new_new_arr(new_arr.begin(), new_arr.end());
                        new_new_arr.erase(new_new_arr.begin() + j);
                        pair<char, char> p = dfs(turn + 1, j);
