int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int max_val = *max_element(a.begin(), a.end());
    int min_val = *min_element(a.begin(), a.end());

    int max_pos = -1, min_pos = -1;

    for (int i = 0; i < n; ++i) {
        if (a[i] == max_val) {
            max_pos = i;
        }
        if (a[i] == min_val) {
            min_pos = i;
        }
    }

    int steps = 0;

    // Move max to front
    while (max_pos > 0) {
        swap(a[max_pos], a[max_pos - 1]);
        max_pos--;
        steps++;
    }

    // Move min to end
    while (min_pos < n - 1) {
        swap(a[min_pos], a[min_pos + 1]);
        min_pos++;
        steps++;
    }

    cout << steps << endl;
    return 0;
}

