#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000009;

long long pow_mod(long long a, long long b) {
    long long res = 1;
    a %= MOD;
    while (b > 0) {
        if (b % 2 == 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b /= 2;
    }
    return res;
}

long long solve(int n) {
    long long m = n / 2;
    long long ans = pow_mod(2, 2 * m);
    ans = (ans - 2) % MOD;
    ans = (ans + pow_mod(2, m - 1)) % MOD;
    return ans;
}

int main() {
    int n;
    cin >> n;
    cout << solve(n) << endl;
    return 0;
}

