    vector<pair<long long, long long>> figures(n);
    for (int i = 0; i < n; ++i) {
        long long k, c;
        cin >> k >> c;
        figures[i] = {k, c};
    }
    int t;
    cin >> t;
    vector<long long> p(t);
    for (int i = 0; i < t; ++i) {
        cin >> p[i];
    }

    // Sort the figures by their cost in descending order
    sort(figures.begin(), figures.end(), [](const pair<long long, long long>& a, const pair<long long, long long>& b) {
        return a.second > b.second;
    });

    long long total = 0;
    long long factor = 1;
    long long total_destroyed = 0;

    // We need to track how many figures have been destroyed so far
    // and determine which factor to apply to each figure
    // We will use a priority queue to always take the highest value figure
    // and assign it to the highest possible factor

    vector<long long> factors;
    factors.push_back(1);
    for (int i = 0; i < t; ++i) {
        factors.push_back(i + 2);
    }

    // We need to keep track of how many figures can be assigned to each factor
    // based on the cumulative p values
    vector<long long> factor_counts(t + 2, 0);
    long long prev_p = 0;
    for (int i = 0; i < t; ++i) {
        factor_counts[i + 1] = p[i] - prev_p;
        prev_p = p[i];
    }
    factor_counts[t + 1] = 1e18; // More than enough for the rest

    // Use a max heap to always take the highest value figure
    priority_queue<pair<long long, long long>> pq;
    for (auto& f : figures) {
        pq.push({f.second, f.first});
    }

    // Now assign figures to factors in a way that maximizes points
    long long current_factor = 0;
    long long current_count = 0;
    while (!pq.empty()) {
        long long cost = pq.top().first;
        long long count = pq.top().second;
        pq.pop();

        // Determine the next factor we can assign
        while (current_factor < t + 1 && current_count + factor_counts[current_factor] <= total_destroyed) {
            current_factor++;
        }

        if (current_factor >= t + 1) {
            // All figures are assigned to the last factor
            total += cost * count * (t + 1);
            total_destroyed += count;
            continue;
        }

        long long available = factor_counts[current_factor];
        long long assign = min(count, available);
        total += cost * assign * (current_factor + 1);
        total_destroyed += assign;
        count -= assign;
        if (count > 0) {
            pq.push({cost, count});
        }
    }

    return total;
}

