    sort(figures.begin(), figures.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.second > b.second;
    });

    long long total = 0;
    long long factor = 1;
    long long total_figures = 0;

    // We need to track the current factor and when it changes
    // The factor increases at p[0], p[1], ..., p[t-1]
    // So we can simulate the process of destroying figures with different factors

    // We will use a priority queue to always pick the figure with the highest cost
    // But since we have to consider the factor, we need to process figures in batches
    // based on the factor thresholds.

    // Let's create a list of factor thresholds
    vector<long long> factor_thresholds = {0};
    for (int i = 0; i < t; ++i) {
        factor_thresholds.push_back(p[i]);
