    factor_thresholds.push_back(1e18); // A large number beyond the last threshold

    // Now, we process each factor level
    for (int i = 0; i < t + 1; ++i) {
        long long current_factor = i + 1;
        long long prev_threshold = factor_thresholds[i];
        long long next_threshold = factor_thresholds[i + 1];

        long long available_figures = next_threshold - prev_threshold;
        long long remaining = available_figures;

        // For each figure type, we can take up to 'remaining' figures
        for (auto& fig : figures) {
