#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

long long solve() {
    int n;
    cin >> n;
    vector<pair<int, int>> figures(n);
    for (int i = 0; i < n; ++i) {
        int k, c;
        cin >> k >> c;
        figures[i] = {k, c};
    }
    int t;
    cin >> t;
    vector<long long> p(t);
    for (int i = 0; i < t; ++i) {
        cin >> p[i];
    }

    // Sort figures by cost in descending order to maximize points
    sort(figures.begin(), figures.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
        return a.second > b.second;
    });

    long long total = 0;
    long long current_factor = 1;
    long long total_destroyed = 0;

    // We need to track the factor changes
    vector<long long> factor_changes = {1}; // Initially factor is 1
    for (int i = 0; i < t; ++i) {
        factor_changes.push_back(i + 2);
    }

    // Now, we process each figure type
    for (auto& fig : figures) {
        int count = fig.first;
        int cost = fig.second;

        // How many of these can be destroyed under the current factor?
        long long available = p[t - 1] - total_destroyed;
        long long take = min(count, available);
        total += take * cost * current_factor;
        total_destroyed += take;
        count -= take;

        if (count == 0)
            continue;

        // Find the next factor change
        long long next_p = p[t - 1];
        if (total_destroyed >= next_p) {
            current_factor++;
            t--;
        }
    }

    return total;
}

int main() {
    cout << solve() << endl;
    return 0;
}

