    dx[1] = 1;  dy[1] = 0; // R
    dx[2] = 0;  dy[2] = -1; // D
    dx[3] = 0;  dy[3] = 1; // U

    vector<vector<int>> moves(n);
    for (int i = 0; i < n; ++i) {
        string curr = s.substr(i, 1);
        if (curr == "L") moves[i].push_back(0);
        else if (curr == "R") moves[i].push_back(1);
        else if (curr == "D") moves[i].push_back(2);
        else if (curr == "U") moves[i].push_back(3);
    }

    set<pair<int, int>> possible_positions;

    for (int x = -n; x <= n; ++x) {
        for (int y = -n; y <= n; ++y) {
            bool valid = true;
            int curr_x = x, curr_y = y;
            for (int i = 0; i < n; ++i) {
                bool found = false;
                for (int dir : moves[i]) {
                    int nx = curr_x + dx[dir];
                    int ny = curr_y + dy[dir];
                    if (nx >= -n && nx <= n && ny >= -n && ny <= n) {
                        curr_x = nx;
                        curr_y = ny;
                        found = true;
                        break;
