    vector<string> res;
    string token;
    for (char c : s) {
        if (c == delimiter) {
            res.push_back(token);
            token.clear();
        } else {
            token += c;
        }
    }
    if (!token.empty()) res.push_back(token);
    return res;
}

bool is_subsequence(const vector<string>& a, const vector<string>& b) {
    int i = 0, j = 0;
    while (i < a.size() && j < b.size()) {
        if (a[i] == b[j]) {
            i++;
            j++;
        } else {
            j++;
        }
    }
    return i == a.size();
}

int count_inversions(const vector<string>& perm, const vector<string>& original) {
    int inv = 0;
    for (int i = 0; i < perm.size(); ++i) {
        for (int j = i + 1; j < perm.size(); ++j) {
            if (original[perm[i]] > original[perm[j]]) {
                inv++;
            }
        }
    }
    return inv;
}

