#include <algorithm>

using namespace std;

int main() {
    int k;
    cin >> k;

    // We can create a complete graph of size m, which has C(m, 3) triangles
    // Find the smallest m such that C(m, 3) >= k
    int m = 3;
    while ((m * (m - 1) * (m - 2)) / 6 < k) m++;

    // Create a complete graph of size m
    vector<vector<char>> adj(m, vector<char>(m, '0'));
    for (int i = 0; i < m; ++i) {
        for (int j = i + 1; j < m; ++j) {
            adj[i][j] = '1';
            adj[j][i] = '1';
        }
    }

    // Now we need to add more triangles by connecting new nodes to existing ones
    // To avoid exceeding 100 nodes, we can add new nodes and connect them to some existing nodes
    // Each new node connected to t existing nodes adds C(t, 2) new triangles

    int remaining = k;
    int current_nodes = m;
    while (remaining > 0 && current_nodes <= 100) {
        int t = 2;
        while (remaining > 0 && (t * (t - 1)) / 2 <= remaining) {
            t++;
        }
        t--;

        // Add a new node and connect it to t existing nodes
        vector<char> new_row(m + 1, '0');
        for (int i = 0; i < t; ++i) {
            new_row[i] = '1';
        }
        adj.push_back(new_row);
        for (int i = 0; i < t; ++i) {
            adj[i][adj.size() - 1] = '1';
            adj[adj.size() - 1][i] = '1';
        }

        // Calculate how many new triangles this added node contributes
        int added_triangles = (t * (t - 1)) / 2;
        remaining -= added_triangles;
        current_nodes++;
    }

    // Output the result
    cout << adj.size() << endl;
    for (const auto& row : adj) {
        for (char c : row) {
            cout << c;
        }
        cout << endl;
    }

    return 0;
}

