        graph[i][i] = 0;
        graph[i][(i + 1) % 3] = 1;
        graph[i][(i + 2) % 3] = 1;
    }

    // Add more nodes to create additional triangles
    int current_nodes = 3;
    while (k > 1) {
        // Add a new node connected to all previous nodes
