        vector<int> new_row(current_nodes, 0);
        for (int i = 0; i < current_nodes - 1; ++i) {
            new_row[i] = 1;
        }
        graph.push_back(new_row);

        // Add edges between the new node and all existing nodes
        for (int i = 0; i < current_nodes - 1; ++i) {
