using namespace std;

double expected_score(int n, vector<double> p) {
    double res = 0.0;
    double curr = 0.0;
    for (int i = 0; i < n; ++i) {
        double pi = p[i];
        double prob = pi * (1 - curr);
        res += prob * (curr + 1) * (curr + 1);
        curr = pi * curr + pi;
    }
    return res;
}

