#include <bits/stdc++.h>
using namespace std;

int main() {
    long long n, d;
    cin >> n >> d;
    vector<long long> x(n);
    for (long long i = 0; i < n; ++i)
        cin >> x[i];
    long long ans = 0;
    for (long long i = 0; i < n; ++i) {
        long long j = i + 1;
        while (j < n && x[j] - x[i] <= d) ++j;
        long long k = j - 1;
        long long m = k - 1;
        while (m >= i + 1) {
            long long l = m - 1;
            while (l >= i + 1 && x[l] - x[i] <= d) --l;
            ans += l - i;
            --m;
        }
    }
    cout << ans << endl;
}

