    vector<int> result(p.size());
    for (int i = 0; i < p.size(); ++i) {
        result[q[i] - 1] = p[i];
    }
    return result;
}

vector<int> inverse_permutation(vector<int>& q) {
    vector<int> inv(q.size());
    for (int i = 0; i < q.size(); ++i) {
        inv[q[i] - 1] = i + 1;
    }
    return inv;
}

