    // Check if total area can be covered
    int total_area = n * m;
    int area_covered_by_1x2 = a * 2;
    int area_covered_by_2x1 = b * 2;
    int area_covered_by_2x2 = c * 4;
    if (area_covered_by_1x2 + area_covered_by_2x1 + area_covered_by_2x2 < total_area) {
        cout << "IMPOSSIBLE" << endl;
        return;
    }

    // Check if the area is even or odd
    if ((n * m) % 2 != 0) {
        if (c == 0) {
            cout << "IMPOSSIBLE" << endl;
            return;
        }
        // If there are 2x2 planks, check if they can cover the odd area
        int remaining_area = total_area - (c * 4);
        if (remaining_area % 2 != 0) {
            cout << "IMPOSSIBLE" << endl;
            return;
        }
    }

    // Initialize grid
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            grid[i][j] = 'a';

    int x = 0, y = 0;
    char curr_char = 'a';

    // Try to place 2x2 planks first
    for (int i = 0; i < c && x < n && y < m; ) {
        if (x + 1 < n && y + 1 < m) {
            // Place 2x2 plank
            for (int dx = 0; dx < 2; ++dx)
                for (int dy = 0; dy < 2; ++dy)
                    grid[x + dx][y + dy] = curr_char;
            curr_char++;
            x += 2;
            y += 2;
            c--;
        } else {
            // Place 1x2 or 2x1 plank
            if (x + 1 < n) {
                // Place 1x2
                for (int dx = 0; dx < 2; ++dx)
                    grid[x + dx][y] = curr_char;
                curr_char++;
                x += 2;
                y++;
            } else if (y + 1 < m) {
                // Place 2x1
                for (int dy = 0; dy < 2; ++dy)
                    grid[x][y + dy] = curr_char;
                curr_char++;
                y += 2;
                x++;
            } else {
                break;
            }
        }
    }

    // Place remaining 1x2 and 2x1 planks
    while (a > 0 || b > 0) {
        if (x + 1 < n) {
            // Place 1x2
            for (int dx = 0; dx < 2; ++dx)
                grid[x + dx][y] = curr_char;
            curr_char++;
            x += 2;
            y++;
