    int m;
    cin >> m;
    vector<int> q(m);
    for (int i = 0; i < m; ++i)
        cin >> q[i];

    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i)
        cin >> a[i];

    sort(a.begin(), a.end());

    // Find the best discount
    int best_q = 0;
    int min_cost = 0;
    int free = 0;

    for (int i = 0; i < m; ++i) {
        int q_val = q[i];
        int cost = 0;
        int free_count = 0;
        int idx = 0;

        while (idx < n) {
            // Buy q_val items
            for (int j = 0; j < q_val && idx < n; ++j)
                cost += a[idx++];

            // Get up to 2 free items
            for (int j = 0; j < 2 && idx < n; ++j)
                free_count++;
        }

        if (free_count > 0) {
            // We can get some free items, so we need to subtract their cost
            // but only if they are cheaper than the cheapest in the basket
            // since we sorted a, the first free items are the cheapest
            // so we can subtract up to 2 * min_price
            int min_price = a[0];
            min_cost = cost - min_price * free_count;
        } else {
            min_cost = cost;
        }

        if (min_cost < best_cost) {
            best_cost = min_cost;
            best_q = q_val;
        }
    }

    // Also consider not using any discount
    int no_discount = 0;
    for (int i = 0; i < n; ++i)
        no_discount += a[i];

