    for (int i = 0; i < n; ++i)
        cin >> a[i];

    unordered_map<int, int> freq;
    for (int x : a) {
        int f = 0;
        while (x > 0) {
            if (x % 2 == 1)
                f++;
            x /= 2;
        }
        freq[f]++;
    }

    long long ans = 0;
    for (auto& [k, v] : freq) {
        ans += v * (v - 1) / 2;
    }

    cout << ans << endl;
    return 0;
}

