int main() {
    int n;
    cin >> n;
    vector<long long> seq = {0};
    long long sum = 0;
    for (int i = 0; i < n; ++i) {
        int t;
        cin >> t;
        if (t == 1) {
            int ai, xi;
            cin >> ai >> xi;
            for (int j = 0; j < ai; ++j) {
                seq[j] += xi;
            }
            sum += ai * xi;
        } else if (t == 2) {
            long long ki;
            cin >> ki;
            seq.push_back(ki);
            sum += ki;
        } else {
            seq.pop_back();
            sum -= seq.back();
        }
        cout << fixed << setprecision(6) << (double)sum / seq.size() << endl;
    }
    return 0;
}

