#include <iostream>
#include <vector>
#include <cmath>

using namespace std;

bool isPrime(int n) {
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % 2 == 0) return false;
    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0) return false;
    }
    return true;
}

int countPrimitiveRoots(int p) {
    int phi = p - 1;
    vector<int> factors;
    int temp = phi;
    for (int i = 2; i <= sqrt(temp); ++i) {
        while (temp % i == 0) {
            factors.push_back(i);
            temp /= i;
        }
    }
    if (temp > 1) factors.push_back(temp);

    int result = 1;
    for (int factor : factors) {
        result *= (p - 1) / factor;
    }
    return result;
}

int main() {
    int p;
    cin >> p;
    cout << countPrimitiveRoots(p) << endl;
    return 0;
}

