#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> tasks(n);
    for (int i = 0; i < n; ++i) {
        cin >> tasks[i].first >> tasks[i].second;
    }

    int queueSize = 0;
    int maxQueue = 0;
    int lastSentTime = 0;

    for (auto& task : tasks) {
        int time = task.first;
        int count = task.second;

        // Calculate how many messages can be sent before this task arrives
        int messagesSent = time - lastSentTime;
        queueSize -= messagesSent;
        lastSentTime = time;

        // Add the new messages to the queue
        queueSize += count;

        // Update max queue size
        if (queueSize > maxQueue) {
            maxQueue = queueSize;
        }
    }

    // After all tasks, send remaining messages
    while (queueSize > 0) {
        queueSize--;
        lastSentTime++;
    }

    cout << lastSentTime << " " << maxQueue << endl;
    return 0;
}

