#include <queue>
#include <vector>
#include <unordered_map>

using namespace std;

struct Move {
    char dir;
    int x, y;
};

struct State {
    int x, y;
    int steps;
    string path;
};

bool isValid(int x, int y) {
    return x >= 0 && x < 8 && y >= 0 && y < 8;
}

int main() {
    string s, t;
    cin >> s >> t;

    int sx = s[0] - 'a';
    int sy = 10 - (s[1] - '0');
    int tx = t[0] - 'a';
    int ty = 10 - (t[1] - '0');

    queue<State> q;
    q.push({sx, sy, 0, ""});

    unordered_map<int, unordered_map<int, bool>> visited;
    visited[sx][sy] = true;

    while (!q.empty()) {
        State current = q.front();
        q.pop();

        if (current.x == tx && current.y == ty) {
            cout << current.steps << endl;
            cout << current.path << endl;
            return 0;
        }

        vector<Move> directions = {
            {'L', -1, 0}, {'R', 1, 0}, {'U', 0, -1}, {'D', 0, 1},
            {'LU', -1, -1}, {'LD', -1, 1}, {'RU', 1, -1}, {'RD', 1, 1}
        };

        for (auto& dir : directions) {
            int nx = current.x + dir.x;
            int ny = current.y + dir.y;

            if (isValid(nx, ny) && !visited[nx][ny]) {
                visited[nx][ny] = true;
                string newPath = current.path + dir.dir;
                q.push({nx, ny, current.steps + 1, newPath});
            }
        }
    }

    return 0;
}

