            // Add command
            string name = line.substr(1);
            chat[name] = 1;
        } else if (line[0] == '-') {
            // Remove command
            string name = line.substr(1);
            chat[name] = 0;
        } else {
            // Send command
            size_t colon_pos = line.find(':');
            string sender = line.substr(0, colon_pos);
            string message = line.substr(colon_pos + 1);
            int count = 0;
            for (auto& pair : chat) {
                if (pair.second == 1) {
                    count++;
                }
            }
            total_traffic += count * message.length();
        }
    }

    cout << total_traffic << endl;
    return 0;
