    s = stack<int>();
    for (int i = n - 1; i >= 0; --i) {
        while (!s.empty() && h[s.top()] < h[i]) {
            prev_greater[s.top()] = i;
            s.pop();
        }
        s.push(i);
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        if (next_greater[i] != -1) ans++;
        if (prev_greater[i] != -1) ans++;
    }

