    for (int i = 0; i < n; ++i) {
        int max1 = h[i];
        int max2 = -1;
        int j = (i + 1) % n;
        while (j != i) {
            if (h[j] > max1) {
                max2 = max1;
                max1 = h[j];
            } else if (h[j] > max2) {
                max2 = h[j];
            }
            j = (j + 1) % n;
        }
        ans += max2;
