using namespace std;

const int MAX_HEROES = 7;
const int MAX_LIKES = 42;

struct Hero {
    int id;
    vector<int> likes;
};

int main() {
    int n;
    cin >> n;
    vector<pair<int, int>> likes;
    for (int i = 0; i < n; ++i) {
        string p, q;
        cin >> p >> q;
        int pid = 0;
        for (char c : p) pid = pid * 10 + (c - '0');
        int qid = 0;
        for (char c : q) qid = qid * 10 + (c - '0');
        likes.push_back({pid, qid});
    }

    int a, b, c;
    cin >> a >> b >> c;

    vector<Hero> heroes(7);
    for (int i = 0; i < 7; ++i) {
        heroes[i].id = i;
        heroes[i].likes.clear();
    }

    for (auto& like : likes) {
        heroes[like.first].likes.push_back(like.second);
    }

    int min_diff = INT_MAX;
    int max_likes = 0;

    // Try all possible ways to split 7 heroes into 3 groups
    do {
        vector<int> group[3];
        int group_size[3] = {0, 0, 0};

        // Assign heroes to groups
        for (int i = 0; i < 7; ++i) {
            int g = i % 3;
            group[g].push_back(i);
            group_size[g]++;
        }

        // Calculate experience for each hero
        vector<int> exp(7, 0);
        for (int g = 0; g < 3; ++g) {
            int size = group_size[g];
            int exp_val = 0;
            if (g == 0) exp_val = a / size;
            else if (g == 1) exp_val = b / size;
            else exp_val = c / size;
            for (int h : group[g]) {
                exp[h] = exp_val;
            }
        }

        // Find max and min experience
        int max_exp = *max_element(exp.begin(), exp.end());
        int min_exp = *min_element(exp.begin(), exp.end());
        int diff = max_exp - min_exp;

        if (diff < min_diff) {
            min_diff = diff;
            max_likes = 0;
            // Compute total likes in this grouping
            int total = 0;
            for (int g = 0; g < 3; ++g) {
                set<int> s;
                for (int h : group[g]) {
                    for (int l : heroes[h].likes) {
                        if (s.find(l) != s.end()) total++;
                        else s.insert(l);
                    }
                }
            }
            max_likes = total;
        } else if (diff == min_diff) {
            int total = 0;
            for (int g = 0; g < 3; ++g) {
                set<int> s;
                for (int h : group[g]) {
                    for (int l : heroes[h].likes) {
                        if (s.find(l) != s.end()) total++;
                        else s.insert(l);
                    }
                }
            }
            if (total > max_likes) {
                max_likes = total;
            }
        }
