int main() {
    int n, m, k, t;
    cin >> n >> m >> k >> t;
    set<pair<int, int>> waste;
    for (int i = 0; i < k; ++i) {
        int a, b;
        cin >> a >> b;
        waste.insert({a, b});
    }
    for (int q = 0; q < t; ++q) {
        int i, j;
        cin >> i >> j;
        if (waste.find({i, j}) != waste.end()) {
            cout << "Waste" << endl;
        } else {
            int pos = 0;
            for (int row = 1; row <= n; ++row) {
                for (int col = 1; col <= m; ++col) {
                    if (row == i && col == j) break;
                    if (waste.find({row, col}) == waste.end()) ++pos;
                }
            }
            switch (pos % 3) {
                case 0: cout << "Carrots" << endl; break;
                case 1: cout << "Kiwis" << endl; break;
                case 2: cout << "Grapes" << endl; break;
            }
        }
    }
    return 0;
}

