#include <bits/stdc++.h>
using namespace std;

string min_string(string s) {
    string min_s = s;
    for (int i = 0; i < s.length(); ++i) {
        string rev = s;
        for (int j = 0; j < s.length() / 2; ++j) {
            swap(rev[j], rev[s.length() - 1 - j]);
        }
