#include <iostream>
#include <vector>
using namespace std;

vector<vector<char>> grid;
char currentChar = 'a';

void placeDomino(int r1, int c1, int r2, int c2) {
    grid[r1][c1] = currentChar;
    grid[r2][c2] = currentChar;
    currentChar++;
}

void placeVerticalDomino(int r, int c) {
    grid[r][c] = currentChar;
    grid[r][c + 1] = currentChar;
    currentChar++;
}

void placeHorizontalDomino(int r, int c) {
    grid[r][c] = currentChar;
    grid[r + 1][c] = currentChar;
    currentChar++;
}

void solve(int n) {
    if (n == 1) {
        cout << "aabb\naabb\naabb\naabb\n";
        return;
    }
    if (n % 2 != 0) {
        cout << "-1\n";
        return;
    }

    grid.resize(4, vector<char>(n, ' '));
    currentChar = 'a';

    for (int i = 0; i < n; i += 2) {
        // Place vertical dominoes in the first two columns
        placeVerticalDomino(0, i);
        placeVerticalDomino(1, i);
        placeVerticalDomino(2, i);
        placeVerticalDomino(3, i);

        // Place horizontal dominoes in the next two columns
        placeHorizontalDomino(i, 0);
        placeHorizontalDomino(i, 1);
    }

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < n; j++) {
            cout << grid[i][j];
        }
        cout << endl;
    }
}

int main() {
    int n;
    cin >> n;
    solve(n);
    return 0;
}

