#include <bits/stdc++.h>
using namespace std;

long long reflection(long long n) {
    long long res = 0;
    while (n > 0) {
        int d = n % 10;
        res = res * 10 + (9 - d);
        n /= 10;
    }
    return res;
}

long long weight(long long n) {
    return n * reflection(n);
}

long long max_weight(long long l, long long r) {
    long long max_w = 0;
    for (long long i = l; i <= r; ++i) {
        long long w = weight(i);
        if (w > max_w) max_w = w;
    }
    return max_w;
}

int main() {
    long long l, r;
    cin >> l >> r;
    cout << max_weight(l, r) << endl;
    return 0;
}

