using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    char grid[n][m];
    for (int i = 0; i < n; ++i) {
        cin >> grid[i];
    }

    map<char, bool> row_count, col_count;

    for (int i = 0; i < n; ++i) {
        map<char, int> row_map;
        for (int j = 0; j < m; ++j) {
            row_map[grid[i][j]]++;
        }
        for (auto& pair : row_map) {
            if (pair.second > 1) {
                row_count[pair.first] = true;
            }
        }
    }

    for (int j = 0; j < m; ++j) {
        map<char, int> col_map;
        for (int i = 0; i < n; ++i) {
            col_map[grid[i][j]]++;
        }
        for (auto& pair : col_map) {
            if (pair.second > 1) {
                col_count[pair.first] = true;
            }
        }
    }

    string result;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (!(row_count[grid[i][j]] || col_count[grid[i][j]])) {
                result += grid[i][j];
            }
        }
    }

    cout << result << endl;
    return 0;
}

