#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100010;

struct Ring {
    int a, b, h;
};

int main() {
    int n;
    cin >> n;
    Ring rings[MAXN];
    for (int i = 0; i < n; ++i) {
        cin >> rings[i].a >> rings[i].b >> rings[i].h;
    }

    // Sort rings by outer radius in increasing order, then by inner radius in decreasing order
    sort(rings, rings + n, [](Ring a, Ring b) {
        if (a.b != b.b) return a.b < b.b;
        return a.a > b.a;
    });

    // DP to find maximum height
    long long dp[MAXN];
    dp[0] = rings[0].h;
    for (int i = 1; i < n; ++i) {
        dp[i] = dp[i - 1] + rings[i].h;
        for (int j = 0; j < i; ++j) {
            if (rings[j].b >= rings[i].b && rings[j].a < rings[i].a) {
                dp[i] = max(dp[i], dp[j] + rings[i].h);
            }
        }
    }

    cout << *max_element(dp, dp + n) << endl;
    return 0;
}

