using namespace std;

const int MAXN = 2e5 + 10;

vector<vector<int>> adj[MAXN];
int color[MAXN];
int time_counter = 1;
int k = 0;

void dfs(int node, int parent) {
    int cnt = 0;
    for (int neighbor : adj[node]) {
        if (neighbor != parent) {
            cnt++;
            if (color[neighbor] == 0) {
                color[neighbor] = color[node] + 1;
                dfs(neighbor, node);
            } else {
                if (color[neighbor] == color[node]) {
                    color[node] = time_counter++;
                    k = max(k, color[node]);
                }
            }
        }
    }
    if (cnt > 1) {
        color[node] = time_counter++;
        k = max(k, color[node]);
    }
}

int main() {
    int n;
