            res.push_back(i);
            while (x % i == 0) x /= i;
        }
    }
    if (x > 1) res.push_back(x);
    return res;
}

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    // Check if the gcd of the original array is > 1
    int g = a[0];
    for (int i = 1; i < n; ++i) g = __gcd(g, a[i]);
    if (g > 1) {
        cout << "YES\n0";
        return 0;
    }

    // Try all possible factors of a[0] and a[1]
    vector<int> factors_a0 = get_factors(a[0]);
    vector<int> factors_a1 = get_factors(a[1]);

    // Try all possible common factors of a[0] and a[1]
    map<int, int> common_factors;
    for (int f : factors_a0) {
        if (find(factors_a1.begin(), factors_a1.end(), f) != factors_a1.end()) {
            common_factors[f] = 0;
        }
    }

    // Try to find the minimal steps
    int min_ops = INT_MAX;
    for (auto& [f, _] : common_factors) {
        int ops = 0;
        vector<int> new_a = a;
        for (int i = 0; i < n; i += 2) {
            if (new_a[i] % f != 0 || new_a[i + 1] % f != 0) {
                // Need to perform operation
