                new_a[i] = val - new_a[i + 1];
                new_a[i + 1] = val + new_a[i + 1];
                ops++;
            }
        }
        // Check if all elements are divisible by f
        bool ok = true;
        for (int x : new_a) {
            if (x % f != 0) {
                ok = false;
                break;
            }
        }
        if (ok) min_ops = min(min_ops, ops);
    }

    if (min_ops != INT_MAX) {
        cout << "YES\n" << min_ops;
    } else {
        cout << "NO";
    }
    return 0;
}

