#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

double poisson_prob(double lambda, int k) {
    double prob = exp(-lambda) * pow(lambda, k) / factorial(k);
    return prob;
}

long long factorial(int n) {
    long long res = 1;
    for (int i = 2; i <= n; ++i)
        res *= i;
    return res;
}

bool is_poisson(const vector<int>& data) {
    double lambda = 0.0;
    for (int k : data) {
        lambda += k;
    }
    lambda /= data.size();

    double sum_poisson = 0.0;
    for (int k : data) {
        sum_poisson += poisson_prob(lambda, k);
    }

    double uniform_prob = 1.0 / (2 * data[0] + 1); // assuming P is data[0]
    double sum_uniform = 0.0;
    for (int k : data) {
        if (k >= 0 && k <= 2 * data[0]) {
            sum_uniform += uniform_prob;
        }
    }

    return sum_poisson > sum_uniform;
}

