    for (int i = 0; i < V; ++i) {
        vector<int> data(250);
        for (int j = 0; j < 250; ++j)
            cin >> data[j];
        if (is_poisson(data))
            cout << "poisson" << endl;
        else
            cout << "uniform" << endl;
    }
    return 0;
}

