};

vector<Data> parse_input() {
    vector<Data> data;
    int t;
    cin >> t;
    for (int i = 0; i < t; ++i) {
        int n;
        cin >> n;
        vector<int> answers(n);
        for (int j = 0; j < n; ++j) {
            cin >> answers[j];
        }
        data.push_back({answers, n});
    }
    return data;
}

double estimate_population(const vector<int>& answers, int n) {
    double mean = 0.0;
    for (int a : answers) {
        mean += a;
    }
    mean /= n;

    // Try Poisson distribution
    double lambda_poisson = mean;
    double poisson_likelihood = exp(-lambda_poisson) * pow(lambda_poisson, n) / pow(1.0, n);

    // Try uniform distribution
    double min_val = *min_element(answers.begin(), answers.end());
    double max_val = *max_element(answers.begin(), answers.end());
    double uniform_likelihood = (n / (max_val - min_val)) * (1.0 / (max_val - min_val)) * (n / (max_val - min_val));

    if (poisson_likelihood > uniform_likelihood) {
        return lambda_poisson;
    } else {
        return (min_val + max_val) / 2.0;
    }
}

