const double POISSON_LOG_LAMBDA = log(2.718281828459045);
const double UNIFORM_LOG_A = log(1000.0);
const double UNIFORM_LOG_B = log(1000.0);

double poisson_log_likelihood(vector<int> responses, int lambda) {
    double log_like = 0.0;
    for (int r : responses) {
        if (r < 0) return -1e18;
        log_like += log(lambda) - lambda - lgamma(r + 1);
    }
    return log_like;
}

double uniform_log_likelihood(vector<int> responses, int a, int b) {
    double log_like = 0.0;
    for (int r : responses) {
        if (r < a || r > b) return -1e18;
        log_like += log(b - a + 1);
    }
    return log_like;
}

string determine_distribution(vector<int> responses) {
    vector<int> sorted_resps = responses;
    sort(sorted_resps.begin(), sorted_resps.end());

    int min_resp = sorted_resps[0];
    int max_resp = sorted_resps.back();

    // Check if all responses are non-negative
    bool all_non_negative = true;
    for (int r : responses) {
        if (r < 0) all_non_negative = false;
    }

    if (all_non_negative) {
        // Try Poisson distribution
        double best_poisson_log_like = -1e18;
        double best_lambda = 0.0;
        for (int lambda_candidate = 1; lambda_candidate <= 1000; ++lambda_candidate) {
            double log_like = poisson_log_likelihood(responses, lambda_candidate);
            if (log_like > best_poisson_log_like) {
                best_poisson_log_like = log_like;
                best_lambda = lambda_candidate;
            }
        }

        // Try Uniform distribution
        double best_uniform_log_like = -1e18;
        double best_a = 0.0;
        double best_b = 0.0;
        for (int a_candidate = 1; a_candidate <= 1000; ++a_candidate) {
            for (int b_candidate = a_candidate; b_candidate <= 1000; ++b_candidate) {
                double log_like = uniform_log_likelihood(responses, a_candidate, b_candidate);
                if (log_like > best_uniform_log_like) {
                    best_uniform_log_like = log_like;
                    best_a = a_candidate;
                    best_b = b_candidate;
                }
            }
        }

        if (best_poisson_log_like > best_uniform_log_like) {
            return "poisson";
        } else {
            return "uniform";
        }
    } else {
        // If any response is negative, it must be uniform
        return "uniform";
    }
}

