bool is_poisson(const vector<int>& samples, int P) {
    vector<int> counts(2 * MAX_P + 1, 0);
    for (int x : samples) {
        if (x >= -P && x <= P) {
            counts[x + P] += 1;
        }
    }

    double lambda = 0.0;
    for (int i = 0; i < counts.size(); ++i) {
        lambda += (double)counts[i] * (i - P);
    }
    lambda /= (double)counts.size();

    double poisson_prob = 0.0;
    for (int i = 0; i < counts.size(); ++i) {
        double prob = exp(-lambda) * pow(lambda, i - P) / factorial(abs(i - P));
        poisson_prob += counts[i] * log(prob);
    }

    double uniform_prob = 0.0;
    double range = 2 * P + 1;
    for (int i = 0; i < counts.size(); ++i) {
        double prob = 1.0 / range;
        uniform_prob += counts[i] * log(prob);
    }

    return poisson_prob < uniform_prob;
}

unsigned long long factorial(unsigned int n) {
    unsigned long long res = 1;
    for (unsigned int i = 1; i <= n; ++i) {
        res *= i;
    }
    return res;
