using namespace std;

const int MAX_P = 1000;
const int NUM_SAMPLES = 10000;

double poisson_mean(const vector<int>& samples) {
    double sum = 0.0;
    for (int s : samples) {
        sum += s;
    }
    return sum / samples.size();
}

double uniform_mean(const vector<int>& samples) {
    double sum = 0.0;
    for (int s : samples) {
        sum += s;
    }
    return sum / samples.size();
}

double poisson_var(const vector<int>& samples, double mean) {
    double sum = 0.0;
    for (int s : samples) {
        sum += (s - mean) * (s - mean);
    }
    return sum / samples.size();
}

double uniform_var(const vector<int>& samples) {
    double sum = 0.0;
    for (int s : samples) {
        sum += s * s;
    }
    return sum / samples.size() - uniform_mean(samples) * uniform_mean(samples);
}

string classify_distribution(vector<int> samples) {
    double mean = uniform_mean(samples);
    double var_poisson = poisson_var(samples, mean);
    double var_uniform = uniform_var(samples);

    // Poisson variance is mean, uniform variance is (max^2 - min^2)/12
    // But since we don't know max and min, we use the calculated variances
    if (abs(var_poisson - mean) < abs(var_uniform - mean)) {
        return "poisson";
    } else {
        return "uniform";
    }
}

