#include <cmath>
#include <algorithm>
#include <numeric>
#include <map>

using namespace std;

const int MAX_P = 1000;
const int MAX_N = 100000;

struct Village {
    int P;
    vector<int> responses;
};

bool is_poisson(const vector<int>& responses, int P) {
    if (responses.empty()) return false;

    double lambda = 0.0;
    for (int r : responses) {
        lambda += r + P;
    }
    lambda /= responses.size();

    double log_likelihood = 0.0;
    for (int r : responses) {
        double prob = exp(-lambda) * pow(lambda, r + P) / factorial(r + P);
        log_likelihood += log(prob);
    }

    return log_likelihood > 1e-6;
}

double factorial(int n) {
    if (n < 0) return 0.0;
    double res = 1.0;
    for (int i = 1; i <= n; ++i) {
        res *= i;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    vector<Village> villages(T);

    for (int i = 0; i < T; ++i) {
