        for (int j = 0; j < N; ++j) {
            cin >> villages[i].responses[j];
        }
    }

    for (auto& village : villages) {
        bool poisson = is_poisson(village.responses, village.P);
        cout << (poisson ? "poisson" : "uniform") << endl;
    }

