#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <numeric>
#include <unordered_map>

using namespace std;

const int MAX_P = 1000;
const int NUM_SAMPLES = 10000;

struct Distribution {
    bool is_poisson;
    vector<int> samples;
};

Distribution determine_distribution(const vector<int>& responses, int P) {
    vector<int> poisson_samples;
    vector<int> uniform_samples;

    for (int r : responses) {
        int x = r + P;
        if (x >= 0 && x <= MAX_P) {
            poisson_samples.push_back(x);
        } else {
            uniform_samples.push_back(x);
        }
    }

    // Check if the samples are consistent with Poisson distribution
    // We'll use mean and variance to approximate
    double mean_poisson = 0.0;
    double variance_poisson = 0.0;
    for (int x : poisson_samples) {
        mean_poisson += x;
        variance_poisson += x * x;
    }
    mean_poisson /= poisson_samples.size();
    variance_poisson /= poisson_samples.size();
    variance_poisson -= mean_poisson * mean_poisson;

    // Check if the samples are consistent with Uniform distribution
    // Uniform distribution on [0, P] has mean P/2 and variance P^2 / 12
    double mean_uniform = P / 2.0;
    double variance_uniform = (P * P) / 12.0;

    // Compare variances
    if (abs(variance_poisson - variance_uniform) < 1e-6) {
        return {false, poisson_samples};
    }

    // If variance is close to Poisson's, assume Poisson
    if (abs(variance_poisson - mean_poisson) < 1e-6) {
        return {true, poisson_samples};
    }

    // Otherwise, assume uniform
    return {false, uniform_samples};
}

int main() {
    int T;
    cin >> T;
    for (int t = 0; t < T; ++t) {
        int P;
        cin >> P;
        vector<int> responses(NUM_SAMPLES);
        for (int i = 0; i < NUM_SAMPLES; ++i) {
            cin >> responses[i];
        }

        Distribution dist = determine_distribution(responses, P);
        cout << (dist.is_poisson ? "poisson" : "uniform") << endl;
    }
    return 0;
}

