#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1e9 + 7;

long long solve(string s) {
    long long res = 0;
    long long b_count = 0;
    for (char c : s) {
        if (c == 'a') {
            res = (res + b_count) % MOD;
        } else {
            b_count++;
        }
    }
    return res;
}

int main() {
    string s;
    cin >> s;
    cout << solve(s) << endl;
    return 0;
}

