    return a.r > b.r;
}

double computeSpaciousness(vector<Circle>& circles) {
    vector<vector<bool>> inCircle(circles.size(), vector<bool>(circles.size(), false));
    for (int i = 0; i < circles.size(); ++i) {
        for (int j = 0; j < circles.size(); ++j) {
            if (i == j) continue;
            if (isInside(circles[i], circles[j].x, circles[j].y)) {
                inCircle[i][j] = true;
            }
        }
    }

    vector<vector<double>> dp(circles.size(), vector<double>(2, 0.0));
    dp[0][0] = area(circles[0].r);
    dp[0][1] = 0.0;

