        if (positions[i] == end) end_idx = i;
    }

    bool cw = false, ccw = false;

    // Clockwise direction: each second moves to next position
    // So after n seconds, it should be (start_idx + n) % 4
    if ((start_idx + n) % 4 == end_idx) cw = true;

    // Counter-clockwise direction: each second moves to previous position
    // So after n seconds, it should be (start_idx - n) % 4
    if ((start_idx - n) % 4 == end_idx) ccw = true;

    if (cw && ccw) cout << "undefined";
    else if (cw) cout << "cw";
    else cout << "ccw";

    return 0;
}

