using namespace std;

const int MOD = 1000000007;

long long powmod(long long a, long long b, long long mod) {
    long long res = 1;
    while (b > 0) {
        if (b % 2 == 1) res = (res * a) % mod;
        a = (a * a) % mod;
        b /= 2;
    }
    return res;
}

long long comb(long long n, long long k, long long mod) {
    if (k < 0 || k > n) return 0;
    long long numerator = 1;
    for (long long i = 0; i < k; ++i) numerator = (numerator * (n - i)) % mod;
    long long denominator = 1;
    for (long long i = 1; i <= k; ++i) denominator = (denominator * i) % mod;
    return (numerator * powmod(denominator, mod - 2, mod)) % mod;
}

