    long long n, m;
    cin >> n >> m;
    long long ans = 0;
    for (long long i = 0; i <= m; ++i) {
        long long c = comb(n, i, MOD);
        long long d = powmod(2, m - i, MOD);
        ans = (ans + c * d) % MOD;
    }
