    cin >> n >> m;
    long long ans = 0;
    for (long long i = 0; i <= m; ++i) {
        long long c = comb(n, i, MOD);
        long long d = comb(m, i, MOD);
        ans = (ans + c * d % MOD) % MOD;
    }
